{
  "passageId": "law-interpretation-guarantee",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법의 보편적 적용이라는 성격을 이유로 일상적 의미에 충실하게 해석해야 한다는 당위를 뒷받침한다."
    },
    {
      "id": "R2",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "일상적 의미에 충실한 해석에 ‘문리 해석’이라는 이름을 붙이고 그 위상을 제시한다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "문리 해석만으로 의미를 파악하기 어렵다는 한계에 대응하여 체계적·역사적 해석이라는 보완 방법을 제시한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "문리 해석 외의 해석이 필요하다는 설명을 ‘담보’라는 표현의 사례로 구체화한다."
    },
    {
      "id": "R5",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "담보라는 표현의 의미를 일상적 사용과 성문법 조문이라는 서로 다른 맥락에서 비교한다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보의 법적 의미가 맥락에 따라 달라진다는 설명을 유상 계약에서의 의미와 책임으로 구체화한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보의 법적 의미가 맥락에 따라 달라진다는 설명을 채권에서의 의미와 담보 물권의 사례로 구체화한다."
    },
    {
      "id": "R8",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "사용 맥락을 고려한다는 체계적 해석의 방법을 유상 계약에서 쓰인 담보의 의미 파악에 적용한다."
    },
    {
      "id": "R9",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "사용 맥락을 고려한다는 체계적 해석의 방법을 채권과 관련하여 쓰인 담보의 의미 파악에 적용한다."
    },
    {
      "id": "R10",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "유상 계약과 채권이라는 서로 다른 맥락에서 담보가 각각 무엇을 보장하는지 비교한다."
    },
    {
      "id": "R11",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "매매 계약을 유상 계약에 속하는 하위 종류로 명시한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "거래 대상의 값어치 보장이라는 담보의 의미를 매매 목적물의 기존 하자에 대한 책임으로 구체화한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "매도인이 부담하는 담보 책임의 구체적인 내용을 손해 배상과 계약 파기·환불로 풀어 설명한다."
    },
    {
      "id": "R14",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "기존 하자에 대해 매도인이 책임진다는 원칙에 매수인이 하자를 알았거나 알 수 있었던 경우의 예외를 제시한다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "손해 배상이 원칙이지만 계약 목적을 달성할 수 없으면 파기와 환불도 가능하다는 예외를 제시한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "금전 채권은 돈을 받아야 실현된다는 사실을 근거로 미지급 시 강제 집행을 거쳐야 한다는 필요성을 설명한다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "강제 집행 절차에 대한 설명을 집행 대상이 부동산인 경우의 경매와 배당으로 구체화한다."
    },
    {
      "id": "R18",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "채권액 비례 배당이라는 원칙에 담보 물권자의 우선 배당이라는 예외를 제시한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보 물권자의 우선 배당은 채권의 실현 가능성을 보장하는 조치의 구체적 사례이다."
    },
    {
      "id": "R20",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "채권의 실현 가능성을 보장한다는 담보의 기능을 새로운 대상인 보증에 적용한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증이 담보 기능을 수행한다는 성격으로부터 주채무 소멸 시 보증 채무도 소멸한다는 법적 설명을 도출한다."
    },
    {
      "id": "R22",
      "type": "CONDITION",
      "otherName": "",
      "reason": "채권자와 보증인 사이의 보증 계약을 보증 성립의 필요조건으로 제시한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증인에게만 채무가 발생한다는 사실을 근거로 보증 계약이 유상 계약이 아니라고 판단한다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "당사자 사이의 상호 대가 약속이라는 유상 계약의 기준을 보증 계약에 적용하여 해당 여부를 판단한다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "주채무자와 보증인 사이에 별도의 대가 약정이 있더라도 보증 계약 자체는 유상 계약이 아니라는 점을 밝힌다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증인 보호를 위한 법적 규제를 계약서 작성과 서명·기명 날인이라는 구체적 요건으로 설명한다."
    },
    {
      "id": "R27",
      "type": "CONDITION",
      "otherName": "",
      "reason": "계약서와 서명·기명 날인 요건을 위반한 경우 계약이 무효가 된다는 법적 조건 관계를 제시한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "형식 요건 위반으로 계약이 무효이더라도 보증 채무를 이행한 뒤에는 그 무효를 주장할 수 없다는 한계를 제시한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "특별법에 따른 보호의 구체적 예로 보증 기간이 명시되지 않으면 3년으로 간주하는 규정을 제시한다."
    },
    {
      "id": "R30",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "보증인에게 이행 거절권이 있다는 원칙에 그 권리를 포기하는 연대 보증 특약이 가능하다는 예외를 제시한다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "연대 보증 특약이 이행 거절권의 포기라는 내용으로부터 연대 보증인은 직접 청구를 거절할 수 없다는 결론이 따라 나온다."
    },
    {
      "id": "R32",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "채권자의 직접 청구에 대한 이행 거절 가능성을 기준으로 일반 보증인과 연대 보증인을 비교한다."
    },
    {
      "id": "R33",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "특별법이 제공하는 보호의 설명에서 그 보호가 연대 보증인에게도 적용되는지 묻는 논의로 확장한다."
    },
    {
      "id": "R34",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "연대 보증인의 특성에 대한 설명에서 연대 보증인에 대한 특별법 적용 여부라는 새로운 쟁점으로 넘어간다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법문의 규정과 입법 과정의 강조점이 다르다는 사실을 근거로 해석 방법에 따라 적용 여부의 결론이 달라질 수 있음을 설명한다."
    },
    {
      "id": "R36",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "입법 과정의 논의를 고려한다는 역사적 해석의 방법을 특별법의 연대 보증인 보호 문제에 적용한다."
    },
    {
      "id": "R37",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "법문 표현의 의미에서 출발한다는 문리 해석의 원칙을 특별법 제2조의 적용 대상 규정을 검토하는 데 적용한다."
    }
  ]
}

